from PIL import Image
import numpy as np
def load(d,name):
    return np.array(Image.open(f'test-results/visual-{d}/{name}-expected.png').convert('L')).astype(float), np.array(Image.open(f'test-results/visual-{d}/{name}-actual.png').convert('L')).astype(float)
import itertools
for d,name,box in [('contact-desktop','contact',(835,265,1040,290)),('home-desktop','home',(144,150,640,230))]:
    e,a=load(d,name)
    x0,y0,x1,y1=box
    E=e[y0:y1,x0:x1]
    best=None
    for dy in range(-3,4):
      for dx in range(-3,4):
        A=a[y0+dy:y1+dy,x0+dx:x1+dx]
        err=np.abs(E-A).mean()
        if best is None or err<best[0]: best=(err,dx,dy)
    print(d, 'best shift dx,dy=',best[1],best[2],'err',round(best[0],2),'zero-err',round(np.abs(E-a[y0:y1,x0:x1]).mean(),2))
EOF

