const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({viewport:{width:1280,height:800}});
  await p.goto('http://127.0.0.1:'+(process.env.PORT||4173)+'/contact.html');
  await p.waitForTimeout(500);
  const r = await p.evaluate(async () => {
    await document.fonts.ready;
    const fonts=[...document.fonts].map(f=>({family:f.family,weight:f.weight,status:f.status}));
    const c=document.createElement('canvas').getContext('2d');
    const measure=(font)=>{c.font=font;return c.measureText('Other ways to reach us').width};
    const el=document.querySelector('.contact-card h2, h2');
    const cs=el?getComputedStyle(el):null;
    return {loaded:fonts, check:document.fonts.check('16px \"Acme Sans\"'), wAcme:measure('16px \"Acme Sans\"'), wSystem:measure('16px system-ui'), wSans:measure('16px sans-serif'), h2: cs?{family:cs.fontFamily,weight:cs.fontWeight,size:cs.fontSize,ls:cs.letterSpacing}:null,
      navContact: (()=>{const a=[...document.querySelectorAll('.nav-link')].pop(); return a.getBoundingClientRect().toJSON()})()};
  });
  console.log(JSON.stringify(r,null,2));
  await b.close();
})();
