const { chromium } = require('playwright');
const fs=require('fs');
(async () => {
  const b = await chromium.launch();
  const variants = {
    baseline: '',
    antialiased: 'html{-webkit-font-smoothing:antialiased}',
    subpixel: 'html{-webkit-font-smoothing:subpixel-antialiased}',
    geometric: 'body{text-rendering:geometricPrecision}',
    legibility: 'body{text-rendering:optimizeLegibility}',
    speed: 'body{text-rendering:optimizeSpeed}',
    kernnormal: 'body{font-kerning:normal}',
    kernnone: 'body{font-feature-settings:\"kern\" 0}',
    ligaoff: 'body{font-variant-ligatures:none}',
    synthnone: 'body{font-synthesis:none}',
    smoothning: 'body{-webkit-font-smoothing:antialiased}',
  };
  for (const [name,css] of Object.entries(variants)) {
    const p = await b.newPage({viewport:{width:1280,height:800}});
    await p.goto('http://127.0.0.1:4173/');
    if (css) await p.addStyleTag({content: css});
    await p.waitForTimeout(100);
    await p.screenshot({path: process.env.TMPDIR+'/crops/v_'+name+'.png', fullPage:true});
    await p.close();
  }
  await b.close();
})();
