    if a.shape!=exp.shape: print(os.path.basename(f),'size mismatch',a.shape); continue
    d=np.abs(exp-a)
    print(os.path.basename(f).ljust(28), 'mean', round(d.mean(),4), 'npx>20', int((d>20).sum()), 'n>50', int((d>50).sum()))
