from PIL import Image
import numpy as np
def load(d,name):
    return (np.array(Image.open(f'test-results/visual-{d}/{name}-expected.png').convert('L')).astype(float),
            np.array(Image.open(f'test-results/visual-{d}/{name}-actual.png').convert('L')).astype(float))
def shift(img,dx,dy):
    return np.array(Image.fromarray(img.astype(np.uint8)).transform(img.shape[::-1],Image.AFFINE,(1,0,dx,0,1,dy),resample=Image.BICUBIC)).astype(float)
e,a=load('home-desktop','home')
# 'g' glyph area only, plus other curved glyphs
for box in [(336,155,366,205),(518,155,550,205),(565,155,595,205)]:
    x0,y0,x1,y1=box; E=e[y0:y1,x0:x1]
    res=[]
    for dy in np.arange(-0.5,0.51,0.1):
      best=(1e9,None)
      for dx in np.arange(-0.5,0.51,0.1):
        A=shift(a,dx,dy)[y0:y1,x0:x1]
        err=np.abs(E-A).mean()
        if err<best[0]: best=(err,round(dx,1))
      res.append((round(dy,1),best[0],best[1]))
    print(box,'zeroerr',round(np.abs(E-a[y0:y1,x0:x1]).mean(),3))
    for r in res: print('   dy',r[0],'bestdx',r[2],'err',round(r[1],3))
