    const out=[];
    const walker=document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    while(node=walker.nextNode()){
      const el=node.parentElement;
      if(!el || !node.data.trim()) continue;
      const cs=getComputedStyle(el);
      for(let i=0;i<node.data.length;i++){
        const c=node.data[i]; if(/\s/.test(c)) continue;
        const r=document.createRange(); r.setStart(node,i); r.setEnd(node,i+1);
        const b=r.getBoundingClientRect();
        if(b.width<=0||b.height<=0) continue;
        if(b.top<0||b.bottom>document.documentElement.scrollHeight) continue;
        out.push({c,x:+b.x.toFixed(3),y:+b.y.toFixed(3),w:+b.width.toFixed(3),h:+b.height.toFixed(3),fs:cs.fontSize,fw:cs.fontWeight});
      }
    }
    return out;
  });
  fs.writeFileSync(process.env.TMPDIR+'/crops/chars.json', JSON.stringify(chars));
  console.log('chars',chars.length);
