    h=min(A.shape[0],B.shape[0]); w=min(A.shape[1],B.shape[1])
    return np.abs(A[:h,:w]-B[:h,:w]).mean()
print('actual-vs-expected g', round(cmp(Eg,Ag),3))
best=[]
for i in range(64):
    im=np.array(Image.open(os.environ['TMPDIR']+f'/crops/gp_{i}.png').convert('L')).astype(float)
    G=glyph(im,(0,0,200,150))
    if G.shape!=Eg.shape:
        best.append((float('inf'),i,G.shape)); continue
    best.append((cmp(Eg,G),i,G.shape))
best.sort()
print('best phase matches for expected g:',[(round(m,2),i) for m,i,s in best[:8]])
print('shapes seen:',sorted(set(s for m,i,s in best)))
# also compare expected vs rendered at native phase (translate 0)
EOF

