const { chromium } = require('playwright');
const fs=require('fs');
(async () => {
  const b = await chromium.launch();
  for (const [name,url,size,w,h] of [
    ['home','/','desktop',1280,800],['about','/about.html','desktop',1280,800],
    ['home','/','phone',390,844],['products','/products.html','desktop',1280,800],
    ['contact','/contact.html','phone',390,844]]) {
    const p = await b.newPage({viewport:{width:w,height:h}, deviceScaleFactor:1});
    await p.goto('http://127.0.0.1:4173'+url);
    await p.waitForTimeout(250);
    const rects = await p.evaluate(()=>{
      const out=[];
      document.querySelectorAll('body *').forEach(el=>{
        const r=el.getBoundingClientRect();
        if(r.width<1||r.height<1) return;
        const cs=getComputedStyle(el);
        if(cs.display==='none'||cs.visibility==='hidden') return;
        out.push({tag:el.tagName.toLowerCase(),cls:el.className&&el.className.baseVal!==undefined?el.className.baseVal:el.className,
          x:r.x, y:r.y+window.scrollY, w:r.width, h:r.height,
          text:(el.children.length===0?(el.textContent||'').trim().slice(0,50):'')});
      });
      return out;
    });
    fs.writeFileSync(process.env.TMPDIR+`/crops/rects_${name}_${size}.json`, JSON.stringify(rects));
    await b.close&&0;
    await p.close();
  }
  await b.close();
})();
EOF
