from PIL import Image
import numpy as np, json, os
T=os.environ['TMPDIR']
def deltas(E,A):
    r1,g1,b1=[E[:,:,i].astype(float) for i in range(3)]
    r2,g2,b2=[A[:,:,i].astype(float) for i in range(3)]
    y=0.29889531*(r1-r2)+0.58662247*(g1-g2)+0.11448223*(b1-b2)
    i=0.59597799*(r1-r2)-0.27417610*(g1-g2)-0.32180189*(b1-b2)
    q=0.21147017*(r1-r2)-0.52261711*(g1-g2)+0.31114694*(b1-b2)
    return 0.5053*y*y+0.299*i*i+0.1957*q*q
for name,size in [('home','desktop'),('about','desktop'),('home','phone'),('products','desktop'),('contact','phone')]:
    E=np.array(Image.open(f'test-results/visual-{name}-{size}/{name}-expected.png').convert('RGB'))
    A=np.array(Image.open(f'test-results/visual-{name}-{size}/{name}-actual.png').convert('RGB'))
    d=deltas(E,A)
    tot=d.sum()
    rects=json.load(open(f'{T}/crops/rects_{name}_{size}.json'))
    rows=[]
    for r in rects:
        x0,y0=int(r['x']),int(r['y']); x1,y1=int(r['x']+r['w']+0.999),int(r['y']+r['h']+0.999)
        x0=max(0,x0);y0=max(0,y0);x1=min(d.shape[1],x1);y1=min(d.shape[0],y1)
        if x1<=x0 or y1<=y0: continue
        sub=d[y0:y1,x0:x1]
        rows.append((sub.sum()/max(tot,1), int((sub>1408).sum()), r['tag'], str(r['cls'])[:28], r['text'][:30], (x0,y0,r['w'],r['h'])))
    rows.sort(reverse=True)
    print('=====',name,size,'totalΔ',round(tot/1e6,2),'million')
    for r in rows[:10]: print(f'  {r[0]*100:5.2f}%  n>{int(r[1]):4d}  <{r[2]} class="{r[3]}"> "{r[4]}" {tuple(round(v,1) for v in r[5])}')
EOF

